def merge_cdc(rows: list[dict]) -> list[dict]:
    """Keep the latest row for each integer id, ordered by (event_ts, ingest_seq).
    Remove ids whose latest row has op='D'. Return remaining rows sorted by id."""
    latest: dict[int, dict] = {}
    for row in rows:
        rid = row["id"]
        key = (row["event_ts"], row["ingest_seq"])
        if rid not in latest:
            latest[rid] = row
        else:
            prev_key = (latest[rid]["event_ts"], latest[rid]["ingest_seq"])
            if key >= prev_key:
                latest[rid] = row
    result = [row for rid, row in latest.items() if row["op"] != "D"]
    result.sort(key=lambda r: r["id"])
    return result
