def dependency_order(graph: dict[str, list[str]]) -> list[str]:
    """Return a topological order where every dependency precedes its node.
    Include dependency-only nodes and raise ValueError on a cycle."""
    # Build the full set of nodes: all keys and all values in the lists
    nodes = set(graph.keys())
    for deps in graph.values():
        nodes.update(deps)

    # Build adjacency: for each node, its dependencies (edges dep -> node)
    # We want topological order where dependencies come first.
    # So we treat edges as dep -> node, and do a topological sort.
    # In-degree for each node = number of its dependencies.
    in_degree = {node: 0 for node in nodes}
    # adjacency: dep -> list of nodes that depend on it
    adjacency = {node: [] for node in nodes}

    for node, deps in graph.items():
        for dep in deps:
            adjacency[dep].append(node)
            in_degree[node] += 1

    # Kahn's algorithm
    from collections import deque
    queue = deque()
    for node in nodes:
        if in_degree[node] == 0:
            queue.append(node)

    order = []
    while queue:
        # For deterministic output, we could sort, but the problem doesn't specify.
        # Let's just pop from the left.
        node = queue.popleft()
        order.append(node)
        for neighbor in adjacency[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    if len(order) != len(nodes):
        raise ValueError("Cycle detected in dependency graph")

    return order
